.panel-head h2 { font-size: 14px; letter-spacing: 0.02em; }
.panel-head .sub { font-size: 11px; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 12px; }
th, td { padding: 6px var(--s3); border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
thead th { background: #0b1118; color: var(--muted); font-size: 10px; font-weight: 600; letter-spacing: 0.09em; text-transform: uppercase; white-space: nowrap; position: sticky; top: 0; }
thead th button { display: inline-flex; align-items: center; gap: 3px; padding: 0; border: 0; background: none; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; }
thead th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #101823; }
tbody tr[data-selected="true"] { background: #16202c; box-shadow: inset 2px 0 0 var(--amber); }
tbody tr:last-child td { border-bottom: 0; }
td.rank { color: var(--muted); font-family: var(--mono); width: 38px; }
.name { display: grid; gap: 0; min-width: 170px; }
.name b { font-weight: 600; font-size: 12.5px; }
.name .sub { font-size: 10.5px; }
.pill { display: inline-block; margin-left: 5px; padding: 0 5px; border-radius: 3px; border: 1px solid var(--amber-dim); color: var(--amber); font-size: 9px; font-weight: 600; letter-spacing: 0.07em; text-transform: uppercase; vertical-align: 1px; }
.conf { font-size: 9px; letter-spacing: 0.07em; text-transform: uppercase; color: var(--muted); border: 1px solid var(--line-2); border-radius: 3px; padding: 0 4px; }
.conf[data-level="high"] { color: var(--teal); border-color: #17463c; }
.conf[data-level="medium"] { color: var(--ink-soft); }
.implied { display: flex; align-items: center; gap: var(--s2); }
.bar { width: 74px; height: 4px; border-radius: 2px; background: #1a2430; overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--amber-dim), var(--amber)); }
.plan-link { color: var(--amber); font-size: 11px; font-weight: 600; white-space: nowrap; }
.empty { padding: var(--s7) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.button { min-height: 32px; padding: 0 var(--s3); border: 1px solid var(--line-2); border-radius: 6px; background: var(--panel-2); font-size: 12px; }
.button.primary { background: var(--amber); border-color: var(--amber); color: #1a1405; font-weight: 600; }

/* The detail page: the call, the arithmetic behind it, the plan, and the protocol's peers. */
.detail-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: start; gap: var(--s4); padding-bottom: var(--s3); border-bottom: 1px solid var(--line); }
.detail-head .sub { margin-top: 2px; }
.call { text-align: right; }
.call b { display: block; font-family: var(--display); font-size: 32px; font-weight: 600; line-height: 1.05; }
.call span { color: var(--muted); font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase; }
.grid-2 { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr); gap: var(--s4); margin-top: var(--s4); align-items: start; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: var(--s4); }
.card h2 { font-size: 13px; letter-spacing: 0.02em; margin-bottom: var(--s3); }
.card h2 span { color: var(--muted); font-weight: 400; }
.equation { display: grid; gap: 5px; font-family: var(--mono); font-size: 11.5px; }
.equation div { display: flex; justify-content: space-between; gap: var(--s3); padding-bottom: 4px; border-bottom: 1px dotted var(--line-2); }
.equation span { color: var(--muted); }
.formula { margin-top: var(--s3); padding: var(--s2) var(--s3); background: #0b1118; border: 1px solid var(--line); border-radius: 6px; font-family: var(--mono); font-size: 10.5px; line-height: 1.75; color: var(--ink-soft); overflow-wrap: anywhere; }
.steps { margin: 0; padding: 0; list-style: none; display: grid; gap: var(--s2); counter-reset: step; }
.steps li { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: var(--s2); padding-bottom: var(--s2); border-bottom: 1px solid var(--line); }
.steps li:last-child { border-bottom: 0; padding-bottom: 0; }
.steps li::before { counter-increment: step; content: counter(step); font-family: var(--mono); font-size: 10px; color: var(--amber); border: 1px solid var(--amber-dim); border-radius: 3px; width: 18px; height: 18px; display: grid; place-items: center; margin-top: 2px; }
.steps b { display: block; font-weight: 550; font-size: 12.5px; }
.steps .meta { color: var(--muted); font-family: var(--mono); font-size: 10.5px; margin-top: 2px; }
.note { margin-top: var(--s3); color: var(--muted); font-size: 11px; }
.stat-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--s2); }
.stat { background: #0b1118; border: 1px solid var(--line); border-radius: 6px; padding: var(--s2) var(--s3); }
.stat span { display: block; color: var(--muted); font-size: 9.5px; letter-spacing: 0.09em; text-transform: uppercase; }
.stat b { font-family: var(--mono); font-size: 14px; font-weight: 500; }

/* Charts: hand-drawn SVG, a grid, an axis and the marks; no library. */
.chart { margin-top: var(--s2); }
.chart svg { display: block; width: 100%; height: auto; overflow: visible; }
.chart .axis { stroke: var(--line-2); stroke-width: 1; }
.chart .grid-line { stroke: var(--line); stroke-width: 1; stroke-dasharray: 2 4; }
.chart .label { fill: var(--muted); font-family: var(--mono); font-size: 9px; }
.chart .dot { fill: var(--amber); }
.chart .dot.big { fill: var(--teal); }
.chart .bar-mark { fill: var(--amber); }
.chart .bar-mark.alt { fill: var(--violet); }

/* The method page: the measured table, its sample counts and the caveats in plain words. */
.calibration { width: 100%; }
.calibration td.num, .calibration th.num { text-align: right; font-family: var(--mono); }
.meter { height: 6px; border-radius: 3px; background: #1a2430; overflow: hidden; }
.meter i { display: block; height: 100%; background: var(--teal); }
.caveats { margin: var(--s3) 0 0; padding-left: var(--s4); color: var(--ink-soft); font-size: 12px; display: grid; gap: 6px; }
.caveats b { color: var(--ink); font-weight: 600; }

.foot { margin-top: var(--s5); padding-top: var(--s3); border-top: 1px solid var(--line); color: var(--muted); font-size: 10.5px; display: flex; flex-wrap: wrap; gap: var(--s2) var(--s5); }

@media (max-width: 1000px) {
  .grid-2 { grid-template-columns: 1fr; }
  .detail-head { grid-template-columns: 1fr; }
  .call { text-align: left; }
  .stat-row { grid-template-columns: 1fr 1fr; }
}
